import express from "express";
import * as authController from "../controllers/AuthController.js";
import { getAllLdapGroups, getAllLdapGroupsWithDESC, getGroupMembers, syncGroupsAndMembers } from "../util/ldap/ldapUtils.js";
import { authenticateToken } from "../middlewares/auth.js";
import config from "../config/envConfig.js";
import client from "../config/ldapconfig.js";
import { ok, fail } from "../util/response.js";

const router = express.Router();

/**
 * @openapi
 * /login:
 *   post:
 *      summary: Login endpoint
 *      description:This api is used to check if get metthod working or not
 *      responses:
 *         200:
 *             description: OK
 *         500:
 *             description: Server Error
 */
//router.post('/login', login);
// Login route
router.post("/login", authController.loginUser);

// Refresh token route
router.post("/refresh-token", authController.refreshToken);

// Logout route (optional)
router.post("/logout", (req, res) => {
  res.clearCookie("refreshToken");
  return ok(res, {}, "Logged out");
});

router.get("/protected", authenticateToken, authController.protectedRoute);
router.put("/change-language", authenticateToken, authController.changeUserLanguage);
// API endpoint to import groups and users from ldap
router.post("/ldap/importgroups", authenticateToken, authController.syncGroupsAndMembersLdap);
// API endpoint to fetch groups with descriptions from ldap
router.get("/ldap/groupsdesc", authenticateToken, authController.listLdapGroupsWithDesc);

//* API TEST endpoints for ldap *//
// API endpoint to list groups
