// test-ldap
router.get("/ldap/test-ldap", async (req, res) => {
  try {
    const testBase = config.LDAP_GROUP_SEARCH_BASE || config.LDAP_SEARCH_BASE;

    // 1. First bind to the server
    await new Promise((resolve, reject) => {
      client.bind(`${config.LDAP_BIND_USERNAME}@hnhriyadh`, config.LDAP_BIND_PASSWORD, (err) => {
        if (err) return reject(err);
        resolve();
      });
    });

    // 2. Then perform a simple search
    const entries = await new Promise((resolve, reject) => {
      const entries = [];

      client.search(
        testBase,
        {
          scope: "base", // Just test the base exists
          filter: "(objectClass=*)",
          attributes: [], // Request no attributes for simple test
        },
        (err, res) => {
          if (err) return reject(err);

          res.on("searchEntry", (entry) => entries.push(entry.object));
          res.on("error", reject);
          res.on("end", () => resolve(entries));
        }
      );
    });

    return ok(res, {
      baseDN: testBase,
      entries: entries.length > 0 ? entries : "Base DN exists but no entries returned",
    }, "LDAP connection successful");
  } catch (error) {
    return fail(res, "LDAP test failed", 400, {
      error: error.message,
      stack: process.env.NODE_ENV === "development" ? error.stack : undefined,
      currentConfig: {
        bindUser: config.LDAP_BIND_USERNAME,
        searchBase: config.LDAP_GROUP_SEARCH_BASE || config.LDAP_SEARCH_BASE,
        ldapUrl: config.LDAP_URL,
      },
    });
  }
});

export default router;
